#!/home/pc/downloads/Tools/uv/doc/.venv/bin/python3
# -*- coding: utf-8 -*-
"""
郵局存證信函 ODT 自動填寫工具 (單檔獨立版，內建 ODT 範本)
-------------------------------------------------------
使用方式：
    py text1                   -> 自動讀取 text1，產出 text1.odt
    py text1 --pdf             -> 自動讀取 text1，產出 text1.odt 與 text1.pdf
    py text1 --font-size 12    -> 自訂內文字級 (12pt)，產出 text1.odt
    py text1 -fs 12 --pdf      -> 自訂內文字級並同步轉成 PDF
    py -h / py --help          -> 查看完整說明手冊與參數
"""

import argparse
import base64
import io
import os
import re
import shutil
import subprocess
import sys
import zipfile
import zlib
from lxml import etree

# 內建郵局存證信函 ODT 範本資料 (zlib + Base64 編碼，無需外部範本檔)
EMBEDDED_ODT_TEMPLATE_B64 = """"""

NAMESPACES = {
    'office': 'urn:oasis:names:tc:opendocument:xmlns:office:1.0',
    'table': 'urn:oasis:names:tc:opendocument:xmlns:table:1.0',
    'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0',
    'style': 'urn:oasis:names:tc:opendocument:xmlns:style:1.0',
    'draw': 'urn:oasis:names:tc:opendocument:xmlns:drawing:1.0',
    'svg': 'urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0',
    'fo': 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0',
}

CITY_COUNTY_REGEX = (
    r'(臺北市|台北市|新北市|桃園市|臺中市|台中市|臺南市|台南市|高雄市|'
    r'基隆市|新竹市|新竹縣|苗栗縣|彰化縣|南投縣|雲林縣|嘉義市|嘉義縣|'
    r'屏東縣|宜蘭縣|花蓮縣|臺東縣|台東縣|澎湖縣|金門縣|連江縣)'
)


def parse_name_address(line: str):
    """從一行字串中分離出姓名與地址。"""
    cleaned = re.sub(r'^[-\s*#]+\s*', '', line).strip()
    cleaned = re.sub(r'^(寄件人|收件人|副\s*本收件人|副本收件人|副本)[:：\s]\s*', '', cleaned).strip()

    m = re.search(CITY_COUNTY_REGEX, cleaned)
    if m:
        name = cleaned[:m.start()].strip()
        addr = cleaned[m.start():].strip()
        return name, addr

    parts = cleaned.rsplit(maxsplit=1)
    if len(parts) == 2:
        return parts[0].strip(), parts[1].strip()

    return cleaned, ''


def parse_text_file(text_path: str):
    """解析 input text 檔案，取得寄件人、收件人、副本收件人及內文段落。保留空格與縮排。"""
    with open(text_path, 'r', encoding='utf-8') as f:
        raw_lines = f.readlines()

    sender_name = ''
    sender_addr = ''
    recipient_name = ''
    recipient_addr = ''
    copy_recipient_name = ''
    copy_recipient_addr = ''
    body_paragraphs = []
    is_in_body = False

    for line in raw_lines:
        line_no_newline = line.rstrip('\r\n')
        trimmed = line_no_newline.strip()

        if not is_in_body and re.match(r'^[-\s*#]*內容[：:]', trimmed):
            is_in_body = True
            after_colon = re.sub(r'^[-\s*#]*內容[：:]\s*', '', line_no_newline)
            if after_colon.strip():
                body_paragraphs.append(after_colon)
            continue

        if not is_in_body:
            if not trimmed:
                continue
            if re.search(r'^(寄件人|sender)', trimmed, re.I) or (not sender_name and not trimmed.startswith('- 收件人') and not trimmed.startswith('- 副本')):
                name, addr = parse_name_address(trimmed)
                if not sender_name:
                    sender_name, sender_addr = name, addr
                    continue
            if re.search(r'^(收件人|recipient)', trimmed, re.I) or (sender_name and not recipient_name and not trimmed.startswith('- 副本')):
                name, addr = parse_name_address(trimmed)
                if not recipient_name:
                    recipient_name, recipient_addr = name, addr
                    continue
            if re.search(r'^(副本|副\s*本收件人)', trimmed, re.I):
                name, addr = parse_name_address(trimmed)
                copy_recipient_name, copy_recipient_addr = name, addr
                continue
        else:
            if trimmed:
                body_paragraphs.append(line_no_newline)

    return {
        'sender_name': sender_name,
        'sender_addr': sender_addr,
        'recipient_name': recipient_name,
        'recipient_addr': recipient_addr,
        'copy_recipient_name': copy_recipient_name,
        'copy_recipient_addr': copy_recipient_addr,
        'paragraphs': body_paragraphs,
    }


def split_into_grid_lines(paragraphs, chars_per_line=20):
    """將內文段落轉換為每行 20 格的存證信函格式。保留空格。"""
    grid_lines = []
    for para in paragraphs:
        if not para.strip():
            continue
        for i in range(0, len(para), chars_per_line):
            grid_lines.append(para[i:i + chars_per_line])
    return grid_lines


def fill_odt(template_bytes: bytes, output_path: str, data: dict, keep_blank_pages: bool = False, font_size: float = None):
    """將資料填入 ODT 範本（直接使用 bytes 解壓處理）。"""
    grid_lines = split_into_grid_lines(data['paragraphs'], chars_per_line=20)
    total_lines = len(grid_lines)
    pages_needed = max(1, (total_lines + 9) // 10)

    if pages_needed > 10:
        print(f'[警告] 內文共 {total_lines} 行，需要 {pages_needed} 頁，超過範本預設的 10 頁上限！', file=sys.stderr)

    total_pages = 10 if keep_blank_pages else min(10, pages_needed)
    temp_zip = output_path + '.tmp.zip'

    with zipfile.ZipFile(io.BytesIO(template_bytes), 'r') as zin:
        with zipfile.ZipFile(temp_zip, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                xml_bytes = zin.read(item.filename)
                if item.filename == 'content.xml':
                    root = etree.fromstring(xml_bytes)

                    # 若有自訂字級，動態建立自訂字級樣式
                    custom_content_style = 'P_CONTENT_CUSTOM' if font_size else 'P19'
                    if font_size:
                        auto_styles = root.find(f'{{{NAMESPACES["office"]}}}automatic-styles')
                        if auto_styles is None:
                            auto_styles = etree.SubElement(root, f'{{{NAMESPACES["office"]}}}automatic-styles')
                        fs_val = f'{font_size:g}pt' if not str(font_size).endswith('pt') else str(font_size)
                        c_style = etree.SubElement(auto_styles, f'{{{NAMESPACES["style"]}}}style', {
                            f'{{{NAMESPACES["style"]}}}name': custom_content_style,
                            f'{{{NAMESPACES["style"]}}}family': 'paragraph',
                            f'{{{NAMESPACES["style"]}}}parent-style-name': 'Table_20_Contents',
                        })
                        etree.SubElement(c_style, f'{{{NAMESPACES["style"]}}}paragraph-properties', {
                            f'{{{NAMESPACES["fo"]}}}text-align': 'center',
                            f'{{{NAMESPACES["style"]}}}justify-single-word': 'false',
                        })
                        etree.SubElement(c_style, f'{{{NAMESPACES["style"]}}}text-properties', {
                            f'{{{NAMESPACES["fo"]}}}font-size': fs_val,
                            f'{{{NAMESPACES["style"]}}}font-size-asian': fs_val,
                        })

                    # 1. 填入每一頁的頁首（寄件人、收件人、副本收件人）
                    for p_idx in range(total_pages):
                        h_tbl_name = f'表格{1 + p_idx * 3}'
                        h_tbl_list = root.xpath(f'//table:table[@table:name="{h_tbl_name}"]', namespaces=NAMESPACES)
                        if not h_tbl_list:
                            continue
                        h_tbl = h_tbl_list[0]
                        cells = h_tbl.xpath('.//table:table-cell', namespaces=NAMESPACES)
                        if len(cells) < 2:
                            continue
                        b1 = cells[1]
                        ps = b1.xpath('./text:p', namespaces=NAMESPACES)

                        # 寄件人姓名 (p[1])
                        if data['sender_name']:
                            spans = ps[1].xpath('./text:span', namespaces=NAMESPACES)
                            if spans:
                                tabs = spans[0].xpath('./text:tab', namespaces=NAMESPACES)
                                if tabs:
                                    tabs[0].tail = f"姓名: {data['sender_name']}"

                        # 寄件人詳細地址 (p[3])
                        if data['sender_addr']:
                            tabs = ps[3].xpath('./text:tab', namespaces=NAMESPACES)
                            if tabs:
                                tabs[0].tail = f"詳細地址：{data['sender_addr']}"

                        # 收件人姓名 (p[4])
                        if data['recipient_name']:
                            tabs = ps[4].xpath('./text:tab', namespaces=NAMESPACES)
                            if tabs:
                                tabs[0].tail = f"姓名：{data['recipient_name']}"

                        # 收件人詳細地址 (p[6])
                        if data['recipient_addr']:
                            tabs = ps[6].xpath('./text:tab', namespaces=NAMESPACES)
                            if tabs:
                                tabs[0].tail = f"詳細地址：{data['recipient_addr']}"

                        # 副本收件人姓名 (p[7])
                        if data['copy_recipient_name']:
                            spans = ps[7].xpath('./text:span', namespaces=NAMESPACES)
                            if len(spans) >= 4:
                                spans[3].text = f"姓名：{data['copy_recipient_name']}"

                        # 副本收件人詳細地址 (p[8])
                        if data['copy_recipient_addr']:
                            tabs = ps[8].xpath('./text:tab', namespaces=NAMESPACES)
                            if tabs:
                                tabs[0].tail = f"詳細地址：{data['copy_recipient_addr']}"

                    # 2. 填入每一頁的頁尾（總頁數）
                    for p_idx in range(total_pages):
                        f_tbl_name = f'表格{3 + p_idx * 3}'
                        f_tbl_list = root.xpath(f'//table:table[@table:name="{f_tbl_name}"]', namespaces=NAMESPACES)
                        if not f_tbl_list:
                            continue
                        f_tbl = f_tbl_list[0]
                        for p in f_tbl.xpath('.//text:p', namespaces=NAMESPACES):
                            txt = ''.join(p.itertext()).strip()
                            if '本存證信函共' in txt:
                                s_list = p.xpath('./text:s', namespaces=NAMESPACES)
                                if s_list:
                                    s_list[0].set(f'{{{NAMESPACES["text"]}}}c', '2')
                                    s_list[0].tail = f'{pages_needed}  頁，正本 '

                    # 3. 填入內文格位（每行 20 格、每頁 10 行）
                    for p_idx in range(total_pages):
                        g_tbl_name = f'表格{2 + p_idx * 3}'
                        g_tbl_list = root.xpath(f'//table:table[@table:name="{g_tbl_name}"]', namespaces=NAMESPACES)
                        if not g_tbl_list:
                            continue
                        g_tbl = g_tbl_list[0]
                        rows = g_tbl.xpath('./table:table-row', namespaces=NAMESPACES)

                        for r in range(1, 11):
                            line_idx = p_idx * 10 + (r - 1)
                            line_content = grid_lines[line_idx] if line_idx < total_lines else ''
                            cells = rows[r].xpath('./table:table-cell', namespaces=NAMESPACES)
                            for c in range(1, 21):
                                char = line_content[c - 1] if (c - 1) < len(line_content) else ''
                                p_list = cells[c].xpath('./text:p', namespaces=NAMESPACES)
                                if p_list:
                                    p_list[0].text = char if char != '' else None
                                    if font_size:
                                        p_list[0].set(f'{{{NAMESPACES["text"]}}}style-name', custom_content_style)
                                else:
                                    p_new = etree.SubElement(cells[c], f'{{{NAMESPACES["text"]}}}p', {f'{{{NAMESPACES["text"]}}}style-name': custom_content_style})
                                    p_new.text = char if char != '' else None

                    # 4. 移除多餘空白頁次（若未指定保留空白頁）
                    if not keep_blank_pages and pages_needed < 10:
                        body = root.find(f'.//{{{NAMESPACES["office"]}}}text')
                        keep = True
                        to_remove = []
                        first_remove_table = f'表格{1 + pages_needed * 3}'
                        for child in body:
                            name = child.attrib.get(f'{{{NAMESPACES["table"]}}}name', '')
                            if name == first_remove_table:
                                keep = False
                            if not keep:
                                to_remove.append(child)
                        for el in to_remove:
                            body.remove(el)
                        last_child = list(body)[-1]
                        if last_child.attrib.get(f'{{{NAMESPACES["text"]}}}style-name') == 'P38':
                            body.remove(last_child)

                    xml_bytes = etree.tostring(root, encoding='utf-8', xml_declaration=True)
                zout.writestr(item, xml_bytes)

    shutil.move(temp_zip, output_path)
    print(f'[成功] 存證信函已產出至: {output_path} (共 {pages_needed} 頁，{total_lines} 行)')


def convert_to_pdf(odt_path: str, output_dir: str = None):
    """使用 LibreOffice 將 ODT 轉換為 PDF。"""
    if output_dir is None:
        output_dir = os.path.dirname(os.path.abspath(odt_path))
    cmd = ['libreoffice', '--headless', '--convert-to', 'pdf', odt_path, '--outdir', output_dir]
    try:
        res = subprocess.run(cmd, capture_output=True, text=True, check=True)
        pdf_name = os.path.splitext(os.path.basename(odt_path))[0] + '.pdf'
        pdf_path = os.path.join(output_dir, pdf_name)
        print(f'[成功] PDF 已同步產出至: {pdf_path}')
        return pdf_path
    except Exception as e:
        print(f'[警告] PDF 轉檔失敗: {e}', file=sys.stderr)
        return None


def main():
    manual_epilog = """
使用範例：
  %(prog)s text1                         自動讀取 text1，產出 text1.odt (預設字級 14pt)
  %(prog)s text1 --pdf                   自動讀取 text1，產出 text1.odt 與 text1.pdf
  %(prog)s text1 --font-size 12          將內文字級調整為 12pt (預設為 14pt)
  %(prog)s text1 -fs 12.5 --pdf          自訂字級 12.5pt 並同步產出 PDF
  %(prog)s text1 -o out.odt              自訂輸出 ODT 檔案名稱
  %(prog)s text1 --keep-blank-pages      保留範本中全部 10 頁 (預設會自動移除未填寫之空白頁)

輸入檔案格式說明 (相容純文字與 Markdown 格式)：
  - 寄件人 姓名 詳細地址
  - 收件人 姓名 詳細地址
  - 副本 姓名 詳細地址 (選填)
  - 內容：
    第一段內文...
    第二段內文...

字級設定說明：
  - 官方郵局存證信函用紙格式為每頁 10 行、每行 20 格 (一格一字，每頁最多 200 字)。
  - 範本預設字級為 14pt (標楷體)。
  - 格子列高約 0.9cm (約 25.5pt)，建議設定範圍為 10pt ~ 15pt：
      * 11pt ~ 13pt：文字稍小，格子內留白舒適、版面整齊美觀。
      * 14pt       ：官方標準預設值。
      * 15pt 以上  ：字體偏大，若超過 16pt 可能會切到字體上下邊緣或撐開格線。
  - 調整字級僅改變格子內字元顯示大小，不會改變一行 20 字之郵局存證信函法定規格。
"""
    parser = argparse.ArgumentParser(
        description="郵局存證信函 ODT 自動填寫工具 (單檔獨立版，內建 ODT 範本)",
        epilog=manual_epilog,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("text_file", nargs="?", default="text", help="輸入純文字/Markdown檔案路徑 (例如: text 或 text1，預設: text)")
    parser.add_argument("-t", "--text", default=None, help="輸入文字檔案路徑 (同 positional argument)")
    parser.add_argument("-fs", "--font-size", type=float, default=None, help="自訂內文字級大小 (pt)，預設為 14pt (建議範圍: 10 ~ 15)")
    parser.add_argument("-i", "--template", default=None, help="自訂 ODT 範本檔案路徑 (預設使用腳本內建範本)")
    parser.add_argument("-o", "--output", default=None, help="輸出 ODT 檔案路徑 (預設: 和純文字檔名同名之 .odt)")
    parser.add_argument("--keep-blank-pages", action="store_true", help="保留範本中全部 10 頁 (預設會自動刪除未使用的空白頁)")
    parser.add_argument("--pdf", action="store_true", help="同時輸出為 PDF 格式 (需安裝 LibreOffice)")
    args = parser.parse_args()

    input_text = args.text if args.text else args.text_file
    if not os.path.exists(input_text):
        print(f'[錯誤] 找不到文字檔案: {input_text}', file=sys.stderr)
        sys.exit(1)

    if args.font_size is not None:
        if args.font_size <= 0:
            print(f'[錯誤] 字級大小必須大於 0 (目前傳入: {args.font_size})', file=sys.stderr)
            sys.exit(1)
        if args.font_size > 18:
            print(f'[警告] 指定字級 {args.font_size}pt 偏大，格子高度約 0.9cm，文字可能會超出格子邊界。', file=sys.stderr)

    output_path = args.output
    if not output_path:
        base_stem = os.path.splitext(os.path.basename(input_text))[0]
        output_path = os.path.join(os.path.dirname(os.path.abspath(input_text)), f'{base_stem}.odt')

    if args.template:
        if not os.path.exists(args.template):
            print(f'[錯誤] 找不到指定的 ODT 範本檔案: {args.template}', file=sys.stderr)
            sys.exit(1)
        with open(args.template, 'rb') as f:
            template_bytes = f.read()
    else:
        # 優先讀取目錄下由使用者提供的官方範本檔案，確保與真實郵局範本完全一致
        default_tpl = os.path.join(os.path.dirname(os.path.abspath(__file__)), '郵局存證信函用紙.ott檔.odt')
        if os.path.exists(default_tpl):
            with open(default_tpl, 'rb') as f:
                template_bytes = f.read()
        else:
            raw_b64 = EMBEDDED_ODT_TEMPLATE_B64.strip()
            compressed_bytes = base64.b64decode(raw_b64)
            template_bytes = zlib.decompress(compressed_bytes)

    data = parse_text_file(input_text)
    fill_odt(template_bytes, output_path, data, keep_blank_pages=args.keep_blank_pages, font_size=args.font_size)

    if args.pdf:
        convert_to_pdf(output_path)


if __name__ == '__main__':
    main()
